        }

        if (second % 2 == 0) {
            System.out.print(second + " ");
        }

        for (int i = 2; i < number; i++) {
            fibonacci = first + second;
            if (fibonacci % 2 == 0) {
                System.out.print(fibonacci + " ");
            }
            first = second;
            second = fibonacci;
        }

        System.out.println();
    }

    public static void printEvenFibonacciRecursive(int number) {
        for (int i = 0; i < number; i++) {
            int fibonacci = calculateFibonacciRecursive(i);
            if (fibonacci % 2 == 0) {
                System.out.print(fibonacci + " ");
            }
        }

        System.out.println();
    }

    public static void printFibonacciRange(int start, int end) {
        for (int i = start; i <= end; i++) {
